Here's a small, generic money-formatting module built on `Intl.NumberFormat`. It handles any currency and locale, and it keeps `formatPrice` as a thin wrapper so the invoice summary call site doesn't change.

```js
// money.js

const formatterCache = new Map();

function getFormatter(locale, currency, options) {
  const key = JSON.stringify([locale, currency, options]);
  let formatter = formatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      ...options,
    });
    formatterCache.set(key, formatter);
  }
  return formatter;
}

// Number of minor units (e.g. cents) per major unit for a currency.
// USD -> 2, JPY -> 0, KWD -> 3.
function minorUnitDigits(currency) {
  return new Intl.NumberFormat('en', { style: 'currency', currency })
    .resolvedOptions().maximumFractionDigits;
}

/**
 * Create a formatter for amounts stored as integer minor units.
 *
 * @param {object}  [config]
 * @param {string}  [config.currency='USD']  ISO 4217 code
 * @param {string}  [config.locale='en-US']  BCP 47 locale
 * @param {object}  [config.options]         Extra Intl.NumberFormat options
 * @returns {(minorUnits: number) => string}
 */
function createMoneyFormatter({
  currency = 'USD',
  locale = 'en-US',
  options = {},
} = {}) {
  const formatter = getFormatter(locale, currency, options);
  const divisor = 10 ** minorUnitDigits(currency);

  return function formatMoney(minorUnits) {
    if (!Number.isInteger(minorUnits)) {
      throw new TypeError(`Expected integer minor units, got ${minorUnits}`);
    }
    return formatter.format(minorUnits / divisor);
  };
}

// Existing API, unchanged for the invoice summary.
const formatPrice = createMoneyFormatter({ currency: 'USD', locale: 'en-US' });

module.exports = { createMoneyFormatter, formatPrice };
```

**Usage**

```js
formatPrice(123456);  // "$1,234.56"
formatPrice(-500);    // "-$5.00"

const formatEuro = createMoneyFormatter({ currency: 'EUR', locale: 'de-DE' });
formatEuro(123456);   // "1.234,56 €"

const formatYen = createMoneyFormatter({ currency: 'JPY', locale: 'ja-JP' });
formatYen(1500);      // "￥1,500"  (JPY has no minor unit)

const formatAccounting = createMoneyFormatter({
  options: { currencySign: 'accounting' },
});
formatAccounting(-500); // "($5.00)"
```

**Behavior changes from the original:**
- **Thousands separators:** `123456` now renders `$1,234.56`, not `$1234.56`.
- **Negatives:** `-500` now renders `-$5.00`, not `$-5.00`.
- **Validation:** non-integer input (e.g. `12.5`) now throws instead of being silently formatted. Remove the check if callers pass fractional cents on purpose.

If the invoice summary has snapshot tests or exact-string assertions, the first two changes will show up there.

With only one call site, the original two-liner (or `createMoneyFormatter` alone without the cache and options) would be enough. I'd keep the full version only if multi-currency or localization is on the roadmap.

